    52	uint32_t mmu_hal_pages_to_bytes(uint32_t mmu_id, uint32_t page_num)
    53	{
    54	    mmu_page_size_t page_size = mmu_ll_get_page_size(mmu_id);
    55	    uint32_t shift_code = 0;
    56	    switch (page_size) {
    57	        case MMU_PAGE_64KB:
    58	            shift_code = 16;
    59	            break;
    60	        case MMU_PAGE_32KB:
    61	            shift_code = 15;
    62	            break;
    63	        case MMU_PAGE_16KB:
    64	            shift_code = 14;
    65	            break;
    66	        default:
    67	            HAL_ASSERT(shift_code);
    68	    }
    69	    return page_num << shift_code;
    70	}
