    92	void mmu_hal_map_region(uint32_t mmu_id, mmu_target_t mem_type, uint32_t vaddr, uint32_t paddr, uint32_t len, uint32_t *out_len)
    93	{
    94	    uint32_t page_size_in_bytes = mmu_hal_pages_to_bytes(mmu_id, 1);
    95	    HAL_ASSERT(vaddr % page_size_in_bytes == 0);
    96	    HAL_ASSERT(paddr % page_size_in_bytes == 0);
    97	    HAL_ASSERT(mmu_ll_check_valid_paddr_region(mmu_id, paddr, len));
    98	    HAL_ASSERT(mmu_hal_check_valid_ext_vaddr_region(mmu_id, vaddr, len, MMU_VADDR_DATA | MMU_VADDR_INSTRUCTION));
    99	
   100	    uint32_t page_num = (len + page_size_in_bytes - 1) / page_size_in_bytes;
   101	    uint32_t entry_id = 0;
   102	    uint32_t mmu_val;     //This is the physical address in the format that MMU supported
   103	
   104	    *out_len = mmu_hal_pages_to_bytes(mmu_id, page_num);
   105	    mmu_val = mmu_ll_format_paddr(mmu_id, paddr, mem_type);
   106	
   107	    while (page_num) {
   108	        entry_id = mmu_ll_get_entry_id(mmu_id, vaddr);
   109	        mmu_ll_write_entry(mmu_id, entry_id, mmu_val, mem_type);
   110	        vaddr += page_size_in_bytes;
   111	        mmu_val++;
   112	        page_num--;
   113	    }
   114	}
