   116	void mmu_hal_unmap_region(uint32_t mmu_id, uint32_t vaddr, uint32_t len)
   117	{
   118	    uint32_t page_size_in_bytes = mmu_hal_pages_to_bytes(mmu_id, 1);
   119	    HAL_ASSERT(vaddr % page_size_in_bytes == 0);
   120	    HAL_ASSERT(mmu_hal_check_valid_ext_vaddr_region(mmu_id, vaddr, len, MMU_VADDR_DATA | MMU_VADDR_INSTRUCTION));
   121	
   122	    uint32_t page_num = (len + page_size_in_bytes - 1) / page_size_in_bytes;
   123	    uint32_t entry_id = 0;
   124	    while (page_num) {
   125	        entry_id = mmu_ll_get_entry_id(mmu_id, vaddr);
   126	        mmu_ll_set_entry_invalid(mmu_id, entry_id);
   127	        vaddr += page_size_in_bytes;
   128	        page_num--;
   129	    }
   130	}
