   132	bool mmu_hal_vaddr_to_paddr(uint32_t mmu_id, uint32_t vaddr, uint32_t *out_paddr, mmu_target_t *out_target)
   133	{
   134	    HAL_ASSERT(mmu_hal_check_valid_ext_vaddr_region(mmu_id, vaddr, 1, MMU_VADDR_DATA | MMU_VADDR_INSTRUCTION));
   135	    uint32_t entry_id = mmu_ll_get_entry_id(mmu_id, vaddr);
   136	    if (!mmu_ll_check_entry_valid(mmu_id, entry_id)) {
   137	        return false;
   138	    }
   139	
   140	    uint32_t page_size_in_bytes = mmu_hal_pages_to_bytes(mmu_id, 1);
   141	    uint32_t offset = (uint32_t)vaddr % page_size_in_bytes;
   142	
   143	    *out_target = mmu_ll_get_entry_target(mmu_id, entry_id);
   144	    uint32_t paddr_base = mmu_ll_entry_id_to_paddr_base(mmu_id, entry_id);
   145	    *out_paddr = paddr_base | offset;
   146	
   147	    return true;
   148	}
