    52	static inline uint32_t mmu_ll_laddr_to_vaddr(uint32_t laddr, mmu_vaddr_t vaddr_type, mmu_target_t target)
    53	{
    54	    (void)vaddr_type;
    55	    uint32_t vaddr_base = 0;
    56	    if (target == MMU_TARGET_FLASH0) {
