    52	  /* Set stack pointer to the idle thread stack */
    53	
    54	  la   sp, _ebss
    55	  li   t0, SMP_STACK_SIZE
    56	  add  sp, sp, t0
    57	
    58	  /* Set gp pointer */
    59	
    60	  la   gp, __global_pointer$
    61	
    62	  /* Disable all interrupts (i.e. timer, external) in mstatus */
    63	
    64	  csrw CSR_MSTATUS, zero
    65	
    66	  .option pop
    67	
    68	  /* Initialize the Machine Trap-Vector */
    69	
    70	  lui  t0, %hi(_vector_table)
    71	  addi t0, t0, %lo(_vector_table)
    72	  csrw  CSR_MTVEC, t0
    73	
    74	  /* Jump to __esp_start */
    75	
    76	  jal  x1, __esp_start
    77	
    78	  /* We shouldn't return from __esp_start */
    79	
    80	  ret
