    84	/* This is an array of task control block (TCB) for the IDLE thread of each
    85	 * CPU.  For the non-SMP case, this is a a single TCB; For the SMP case,
    86	 * there is one TCB per CPU.  NOTE: The system boots on CPU0 into the IDLE
    87	 * task.  The IDLE task later starts the other CPUs and spawns the user
    88	 * initialization task.  That user initialization task is responsible for
    89	 * bringing up the rest of the system.
    90	 */
   665	 *
   666	 ****************************************************************************/
   667	
   668	static void hardware_initialize(void)
   669	{
