   401	/****************************************************************************
   402	 * Name: nx_start_task
   403	 *
   404	 * Description:
   405	 *   This is the framework for a short duration worker thread.  It off-loads
   406	 *   the board initialization and application start-up from the limited
   407	 *   start-up, initialization thread to a more robust kernel thread.
   408	 *
   409	 * Input Parameters:
   410	 *   None
    20	
    21	/****************************************************************************
    22	 * Included Files
    23	 ****************************************************************************/
    24	
    25	#include <nuttx/config.h>
    26	
    27	#include <assert.h>
    28	#include <stdint.h>
    29	#include <time.h>
    30	
    31	#include <arch/board/board.h>
    32	#include <arch/irq.h>
    33	
    34	#ifdef CONFIG_ARCH_CHIP_ESP32P4
    35	#  include <nuttx/arch.h>
    36	#endif
    37	
    38	#include "chip.h"
    39	#include "esp_irq.h"
    40	
    41	#include "hal/systimer_hal.h"
    42	#include "hal/systimer_ll.h"
    43	#include "periph_ctrl.h"
    44	#include "systimer.h"
    45	
    46	/****************************************************************************
    47	 * Pre-processor Definitions
    48	 ****************************************************************************/
    49	
    50	#if SOC_SYSTIMER_INT_LEVEL
    51	#  define SYSTIMER_TRIGGER_TYPE ESP_IRQ_TRIGGER_LEVEL
    52	#else
    53	#  define SYSTIMER_TRIGGER_TYPE ESP_IRQ_TRIGGER_EDGE
    54	#endif /* SOC_SYSTIMER_INT_LEVEL */
    55	
    56	#if defined(CONFIG_ARCH_CHIP_ESP32P4)
    57	#  define CHIP_SYSTIMER_SOURCE SYSTIMER_TARGET0_INTR_SOURCE
    58	#else
    59	#  define CHIP_SYSTIMER_SOURCE SYSTIMER_TARGET0_EDGE_INTR_SOURCE
    60	#endif
    61	
    62	/****************************************************************************
    63	 * Private Data
    64	 ****************************************************************************/
    65	
    66	/* Systimer HAL layer object */
    67	
    68	static systimer_hal_context_t systimer_hal;
    69	
    70	/****************************************************************************
    71	 * Private Functions
    72	 ****************************************************************************/
    73	
    74	/****************************************************************************
    75	 * Name: systimer_irq_handler
    76	 *
    77	 * Description:
    78	 *   Handler to be executed by the Systimer ISR.
    79	 *
    80	 * Input Parameters:
    81	 *   irq           - IRQ associated to that interrupt.
    82	 *   context       - Interrupt register state save info.
    83	 *   arg           - A pointer to the argument provided when the interrupt
    84	 *                   was registered.
    85	 *
    86	 * Returned Value:
    87	 *   Zero on success; a negated errno value on failure.
    88	 *
    89	 ****************************************************************************/
    90	
    91	static int systimer_irq_handler(int irq, void *context, void *arg)
    92	{
    93	#ifdef CONFIG_ARCH_CHIP_ESP32P4
    94	  static bool marked;
    95	  bool trace = !marked;
    96	
    97	  if (trace)
    98	    {
    99	      marked = true;
   100	      up_putc('x');
   101	    }
   102	#endif
   103	
   104	  systimer_ll_clear_alarm_int(systimer_hal.dev,
   105	                              SYSTIMER_ALARM_OS_TICK_CORE0);
   106	
   107	#ifdef CONFIG_ARCH_CHIP_ESP32P4
   108	  if (trace)
   109	    {
   110	      up_putc('y');
   111	    }
   112	#endif
   113	
   114	  /* Process timer interrupt */
   115	
   116	  nxsched_process_timer();
   117	
   118	#ifdef CONFIG_ARCH_CHIP_ESP32P4
   119	  if (trace)
   120	    {
   121	      up_putc('z');
   122	    }
   123	#endif
   124	
   125	  return OK;
   126	}
