   128	/****************************************************************************
   129	 * Public Functions
   130	 ****************************************************************************/
   131	
   132	/****************************************************************************
   133	 * Name: up_timer_initialize
   134	 *
   135	 * Description:
   136	 *   This function is called during start-up to initialize the timer
   137	 *   interrupt.
   138	 *
   139	 * Input Parameters:
   140	 *   None.
   141	 *
   142	 * Returned Value:
   143	 *   None.
   144	 *
   145	 ****************************************************************************/
   146	
   147	void up_timer_initialize(void)
   148	{
   149	#ifdef CONFIG_ARCH_CHIP_ESP32P4
   150	  PERIPH_RCC_ACQUIRE_ATOMIC(PERIPH_SYSTIMER_MODULE, ref_count)
   151	    {
   152	      if (ref_count == 0)
   153	        {
   154	          systimer_ll_enable_bus_clock(true);
   155	          systimer_ll_reset_register();
   156	        }
   157	    }
   158	#else
   159	  periph_module_enable(PERIPH_SYSTIMER_MODULE);
   160	#endif
   161	
   162	  systimer_hal_init(&systimer_hal);
   163	  systimer_hal_tick_rate_ops_t ops =
   164	    {
   165	      .ticks_to_us = systimer_ticks_to_us,
   166	      .us_to_ticks = systimer_us_to_ticks,
   167	    };
   168	
   169	  systimer_hal_set_tick_rate_ops(&systimer_hal, &ops);
   170	  systimer_ll_set_counter_value(systimer_hal.dev,
   171	                                SYSTIMER_COUNTER_OS_TICK,
   172	                                0);
   173	  systimer_ll_apply_counter_value(systimer_hal.dev,
   174	                                  SYSTIMER_COUNTER_OS_TICK);
   175	  systimer_hal_counter_can_stall_by_cpu(&systimer_hal,
   176	                                        SYSTIMER_COUNTER_OS_TICK, 0,
   177	                                        false);
   178	
   179	  systimer_hal_connect_alarm_counter(&systimer_hal,
   180	                                     SYSTIMER_ALARM_OS_TICK_CORE0,
   181	                                     SYSTIMER_COUNTER_OS_TICK);
   182	  systimer_hal_set_alarm_period(&systimer_hal,
   183	                                SYSTIMER_ALARM_OS_TICK_CORE0,
   184	                                CONFIG_USEC_PER_TICK);
   185	  systimer_hal_select_alarm_mode(&systimer_hal,
   186	                                 SYSTIMER_ALARM_OS_TICK_CORE0,
   187	                                 SYSTIMER_ALARM_MODE_PERIOD);
   188	  systimer_hal_counter_can_stall_by_cpu(&systimer_hal,
   189	                                        SYSTIMER_COUNTER_OS_TICK, 0,
   190	                                        true);
   191	  systimer_hal_enable_alarm_int(&systimer_hal,
   192	                                SYSTIMER_ALARM_OS_TICK_CORE0);
   193	  systimer_hal_enable_counter(&systimer_hal, SYSTIMER_COUNTER_OS_TICK);
   194	
   195	  esp_setup_irq(CHIP_SYSTIMER_SOURCE,
   196	                ESP_IRQ_PRIORITY_DEFAULT,
   197	                SYSTIMER_TRIGGER_TYPE);
   198	
   199	  /* Attach the timer interrupt. */
   200	
   201	  irq_attach(ESP_SOURCE2IRQ(CHIP_SYSTIMER_SOURCE),
   202	             (xcpt_t)systimer_irq_handler,
   203	             NULL);
   204	
   205	  /* Enable the allocated CPU interrupt. */
   206	
   207	  up_enable_irq(ESP_SOURCE2IRQ(CHIP_SYSTIMER_SOURCE));
   208	}
