    45	/****************************************************************************
    46	 * Name: nsh_main
    47	 *
    48	 * Description:
    49	 *   This is the main logic for the case of the NSH task.  It will perform
    50	 *   one-time NSH initialization and start an interactive session on the
    51	 *   current console device.
    52	 *
    53	 ****************************************************************************/
    54	
    55	int main(int argc, FAR char *argv[])
    56	{
    57	  struct sched_param param;
    58	  int ret = 0;
    59	
    60	#ifdef CONFIG_ARCH_CHIP_ESP32P4
    61	  up_putc('n');
    62	#endif
    63	
    64	  /* Check the task priority that we were started with */
    65	
    66	  sched_getparam(0, &param);
    67	  if (param.sched_priority != CONFIG_SYSTEM_NSH_PRIORITY)
    68	    {
    69	      /* If not then set the priority to the configured priority */
    70	
    71	      param.sched_priority = CONFIG_SYSTEM_NSH_PRIORITY;
    72	      sched_setparam(0, &param);
    73	    }
    74	
    75	  /* Initialize the NSH library */
    76	
    77	  nsh_initialize();
    78	
    79	#ifdef CONFIG_ARCH_CHIP_ESP32P4
    80	  up_putc('i');
    81	  up_putc('\n');
    82	#endif
    83	
    84	#ifdef CONFIG_NSH_CONSOLE
    85	  /* If the serial console front end is selected, run it on this thread */
    86	
    87	  ret = nsh_consolemain(argc, argv);
    88	
    89	  /* nsh_consolemain() should not return.  So if we get here, something
    90	   * is wrong.
    91	   */
    92	
    93	  dprintf(STDERR_FILENO, "ERROR: nsh_consolemain() returned: %d\n", ret);
    94	  ret = 1;
    95	#endif
    96	
    97	  return ret;
    98	}
